import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../../api/api';
import { Mail, Lock, User, Phone, LogIn, UserPlus } from 'lucide-react';

export default function AuthPage() {
  const [isRegister, setIsRegister] = useState(false);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [phone, setPhone] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      let response;
      if (isRegister) {
        response = await api.post('/auth/register', { name, email, password, phone });
      } else {
        response = await api.post('/auth/login', { email, password });
      }
      const data = response.data;

      localStorage.setItem('@SobrancelhaExpress:token', data.token);
      localStorage.setItem('@SobrancelhaExpress:user', JSON.stringify({
        _id: data._id,
        name: data.name,
        email: data.email,
        role: data.role,
        profileImage: data.profileImage
      }));

      if (data.role === 'admin' || data.role === 'professional') {
        navigate('/professional/dashboard');
      } else {
        navigate('/cliente/agendar');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Erro ao processar');
    } finally {
      setLoading(false);
    }
  };

  // <--- ADICIONE AQUI O OBJETO styles (era isso que estava faltando)
  const styles = {
    container: {
      height: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: '#FFF6FB',
    },
    authBox: {
      background: '#fff',
      padding: '40px',
      borderRadius: '20px',
      boxShadow: '0 10px 25px rgba(217, 136, 179, 0.2)',
      width: '100%',
      maxWidth: '400px',
      textAlign: 'center'
    },
    logoText: {
      color: '#333',
      fontSize: '28px',
      fontWeight: '700',
      marginBottom: '8px'
    },
    subtitle: {
      color: '#666',
      fontSize: '16px',
      marginBottom: '30px'
    },
    form: {
      display: 'flex',
      flexDirection: 'column',
      gap: '16px'
    },
    inputGroup: {
      display: 'flex',
      alignItems: 'center',
      gap: '12px',
      background: '#F9F9F9',
      padding: '14px 16px',
      borderRadius: '12px',
      border: '1px solid #eee'
    },
    input: {
      border: 'none',
      background: 'transparent',
      outline: 'none',
      flex: 1,
      fontSize: '16px',
      color: '#333'
    },
    button: {
      background: '#D988B3',
      color: 'white',
      border: 'none',
      padding: '15px',
      borderRadius: '12px',
      fontSize: '16px',
      fontWeight: '600',
      cursor: loading ? 'not-allowed' : 'pointer',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      gap: '10px',
      marginTop: '20px',
      transition: 'background 0.3s'
    },
    toggleButton: {
      background: 'none',
      border: 'none',
      color: '#D988B3',
      marginTop: '20px',
      cursor: 'pointer',
      fontSize: '14px',
      textDecoration: 'underline'
    },
    errorBanner: {
      background: '#fee2e2',
      color: '#dc2626',
      padding: '12px',
      borderRadius: '8px',
      marginBottom: '20px',
      fontSize: '14px'
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.authBox}>
        <h1 style={styles.logoText}>Sobrancelha<span>Express</span></h1>
        <p style={styles.subtitle}>{isRegister ? 'Crie sua conta' : 'Bem-vindo de volta!'}</p>

        {error && <div style={styles.errorBanner}>{error}</div>}

        <form onSubmit={handleSubmit} style={styles.form}>
          {isRegister && (
            <>
              <div style={styles.inputGroup}>
                <User size={20} color="#D988B3" />
                <input
                  type="text"
                  placeholder="Nome completo"
                  style={styles.input}
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  required
                />
              </div>

              <div style={styles.inputGroup}>
                <Phone size={20} color="#D988B3" />
                <input
                  type="tel"
                  placeholder="Telefone"
                  style={styles.input}
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  required
                />
              </div>
            </>
          )}

          <div style={styles.inputGroup}>
            <Mail size={20} color="#D988B3" />
            <input
              type="email"
              placeholder="E-mail"
              style={styles.input}
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div style={styles.inputGroup}>
            <Lock size={20} color="#D988B3" />
            <input
              type="password"
              placeholder="Senha"
              style={styles.input}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button type="submit" disabled={loading} style={styles.button}>
            {loading ? 'Processando...' : (
              <>
                <span>{isRegister ? 'Registrar' : 'Entrar'}</span>
                {isRegister ? <UserPlus size={20} /> : <LogIn size={20} />}
              </>
            )}
          </button>
        </form>

        <button
          onClick={() => setIsRegister(!isRegister)}
          style={styles.toggleButton}
        >
          {isRegister ? 'Já tem conta? Faça login' : 'Não tem conta? Registre-se'}
        </button>
      </div>
    </div>
  );
}
